{"explanation":"The inverse of a function reverses its input and output coordinates. Since \(\ln(e^x)=x\), every point \((x,e^x)\) on \(y=e^x\) corresponds to \((e^x,x)\) on \(y=\ln x\); swapping coordinates is exactly reflection across \(y=x\). Use the slider to move a matched pair of reflected points.","manimCode":"const ax = new Axes({
  xRange: [-3, 7, 1],
  yRange: [-3, 7, 1],
  xLength: 6.2,
  yLength: 6.2,
  tips: true
});
ax.moveTo([-0.4, -0.45, 0]);

const expCurve = ax.plot(x => Math.exp(x), {
  color: BLUE,
  xRange: [-2.5, 1.9],
  numSamples: 300
});
const logCurve = ax.plot(x => Math.log(x), {
  color: ORANGE,
  xRange: [0.06, 7],
  numSamples: 300
});

const diagonal = new Polygon({
  vertices: [ax.c2p(-3, -3), ax.c2p(7, 7)],
  color: GRAY
});
diagonal.setStrokeWidth(2).setFillOpacity(0);

const title = new Text({ text: 'Inverse functions reflect across y = x', color: WHITE, fontSize: 28 });
title.moveTo([0, 3.55, 0]);

const expLabel = new MathTex({ latex: 'y=e^x', color: BLUE });
await expLabel.waitForRender();
expLabel.moveTo([2.2, 2.25, 0]);

const logLabel = new MathTex({ latex: 'y=\\ln(x)', color: ORANGE });
await logLabel.waitForRender();
logLabel.moveTo([3.55, 0.75, 0]);

const diagLabel = new MathTex({ latex: 'y=x', color: GRAY });
await diagLabel.waitForRender();
diagLabel.moveTo([-2.5, 1.9, 0]);

let a = 0.45;
const blueDot = new Dot({ point: ax.c2p(a, Math.exp(a)), color: YELLOW });
const orangeDot = new Dot({ point: ax.c2p(Math.exp(a), a), color: YELLOW });
const reflectionSegment = new Polygon({
  vertices: [blueDot.getCenter(), orangeDot.getCenter()],
  color: YELLOW
});
reflectionSegment.setStrokeWidth(2).setFillOpacity(0);

blueDot.addUpdater(d => d.moveTo(ax.c2p(a, Math.exp(a))));
orangeDot.addUpdater(d => d.moveTo(ax.c2p(Math.exp(a), a)));
reflectionSegment.addUpdater(s => {
  s.setVertices([blueDot.getCenter(), orangeDot.getCenter()]);
});

scene.add(ax, diagonal, expCurve, logCurve, title, expLabel, logLabel, diagLabel);
await scene.play(new AnimationGroup([
  new FadeIn(blueDot),
  new FadeIn(orangeDot),
  new Create(reflectionSegment)
]));

const controls = new Controls(scene, { position: 'bottom-left', theme: 'dark', width: 250 });
controls.addSlider({
  label: 'Input x',
  min: -2.3,
  max: 1.9,
  value: a,
  step: 0.05,
  onChange: v => { a = v; }
});
controls.addButton({
  label: 'Reset point',
  onClick: () => { a = 0.45; }
});

await scene.wait(999999);"}

